 function observeObject(clue){observation={...clue,remaining:16};observationAt=performance.now();const q=id=>document.getElementById(id),el=q('field-observation');if(!el)return;el.hidden=false;setText(q('field-observation-title'),clue.object);setText(q('field-observation-copy'),clue.observation);q('field-observation-read').setAttribute('onclick',"Exo.readRecord('"+clue.id+"')");const other=q('exp-transmission');if(other)other.hidden=true;}
