  if(observation){if(!danger&&!paused)observation.remaining-=Math.max(0,Math.min(.1,(now-observationAt)/1000));if(observation.remaining<=0)dismissObservation();}observationAt=now;panel.hidden=!observation||!!danger||!!paused;
  const near=!observation&&!danger&&!paused&&typeof ExoFieldClues!=='undefined'?ExoFieldClues.nearby(ExoWorld.interior,u,ExoFacilities.done):null;
